import fs from "node:fs";
import path from "node:path";
export const DEV_ACTION_DISCOVERY_PATH = path.join(".agent-native", "dev-server.json");
/** Read and validate the lightweight dev-server discovery record. */
export function readDevActionDiscoveryFile(appRoot) {
    const filePath = path.join(appRoot, DEV_ACTION_DISCOVERY_PATH);
    let raw;
    try {
        raw = fs.readFileSync(filePath, "utf8");
    }
    catch (error) {
        if (error?.code !== "ENOENT") {
            console.warn("[agent-native] could not read dev action discovery file:", error);
        }
        return undefined;
    }
    let parsed;
    try {
        parsed = JSON.parse(raw);
    }
    catch (error) {
        console.warn("[agent-native] dev action discovery file is not valid JSON:", error);
        return undefined;
    }
    const candidate = parsed;
    if (!candidate ||
        typeof candidate.origin !== "string" ||
        !Number.isInteger(candidate.pid) ||
        typeof candidate.token !== "string" ||
        typeof candidate.databaseKey !== "string") {
        console.warn("[agent-native] dev action discovery file has an unexpected shape; ignoring it");
        return undefined;
    }
    return candidate;
}
